// Original learning dialogues. No third-party scripts or song lyrics are used.
// Every target response is introduced before the choice and assembly activities.
const item=({text,answerParts,learnNote,...rest})=>({
 text:text.replaceAll('|',''),phrases:text.split('|'),
 answer:answerParts.join(''),answerParts,learnNote,...rest
});
const transfer=(prompt,correct,others,answer,explanation)=>{
 // Stable per sentence, without a repeating left-middle-right lesson pattern.
 answer=([...correct].reduce((n,ch)=>Math.imul(n^ch.codePointAt(0),31)>>>0,17)+answer)%3;
 const options=[...others];options.splice(answer,0,correct);
 return {prompt,options,answer,explanation};
};
const lesson=(activity,partner,scene,image,items)=>({mode:'course-expansion',activity,partner,scene,image,items});

